export function BlogPost({ postId, onBack }: BlogPostProps) {
  const [markdownContent, setMarkdownContent] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const post = postMetadata[postId];

  useEffect(() => {
    if (!post) {
      setError("Post not found");
      setLoading(false);
      return;
    }

    // Load markdown file
    const loadMarkdown = async () => {
      try {
        setLoading(true);
        // In development, we can import directly or fetch from public directory
        // For Bun, we'll fetch from the research_md directory
        const response = await fetch(`/research_md/${post.markdownFile}`);
        
        if (!response.ok) {
          throw new Error(`Failed to load markdown file: ${post.markdownFile}`);
        }
        
        const text = await response.text();
        setMarkdownContent(text);
        setError(null);
      } catch (err) {
        console.error("Error loading markdown:", err);
        setError(err instanceof Error ? err.message : "Failed to load content");
      } finally {
        setLoading(false);
      }
    };

    loadMarkdown();
  }, [postId, post]);

  if (!post) {
    return (
      <div className="research-blog">
        <div className="blog-error">
          <p>Post not found</p>
          <button onClick={onBack} className="blog-back-button">← Back to Blog</button>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="research-blog">
        <div className="blog-loading">
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="research-blog">
        <div className="blog-error">
          <p>Error: {error}</p>
          <button onClick={onBack} className="blog-back-button">← Back to Blog</button>
        </div>
      </div>
    );
  }

  return (
    <div className="research-blog">
      <header className="blog-post-header">
        <div className="blog-post-header-top">
          <button onClick={onBack} className="blog-back-button">← Back to Blog</button>
          <div className="blog-post-meta">
            <span className="blog-post-category">{post.category}</span>
            <span className="blog-post-date">{post.date}</span>
            <span className="blog-post-read-time">{post.readTime}</span>
          </div>
        </div>
        <h1 className="blog-post-header-title">{post.title}</h1>
      </header>

      <main className="blog-post-main">
        <article className="blog-post-article">
          <div className="blog-post-content">
            <MarkdownViewer content={markdownContent} />
          </div>
        </article>
      </main>

      <footer className="blog-footer">
        <div className="blog-footer-content">
          <p className="blog-footer-text">Stay updated with the latest research</p>
          <a href="https://x.com/MorpheumX/" target="_blank" rel="noopener noreferrer" className="blog-footer-link">
            Follow on X
          </a>
        </div>
      </footer>
    </div>
  );
}
