export function App() {
  const [currentPage, setCurrentPage] = useState(() => {
    // Get initial page from URL
    const path = window.location.pathname;
    switch (path) {
      case '/privacy-policy':
        return 'privacy-policy';
      case '/terms-of-service':
        return 'terms-of-service';
      case '/risk-disclosure':
        return 'risk-disclosure';
      case '/research':
      case '/research-blog':
        return 'research-blog';
      case '/':
        return 'home';
      default:
        return 'home';
    }
  });

  // Handle navigation
  const handleNavigation = (e: React.MouseEvent<HTMLAnchorElement>, page: string) => {
    e.preventDefault();
    setCurrentPage(page);
    // Update URL without page reload
    const urlPath = page === 'home' ? '/' : `/${page}`;
    window.history.pushState({}, '', urlPath);
    // Scroll to top of page
    window.scrollTo(0, 0);
  };

  // Apply landing-page class to body for theme (light green → orange)
  useEffect(() => {
    if (currentPage === "home") {
      document.body.classList.add("landing-page");
    } else {
      document.body.classList.remove("landing-page");
    }
    return () => document.body.classList.remove("landing-page");
  }, [currentPage]);

  // Handle browser back/forward buttons
  useEffect(() => {
    const handlePopState = () => {
      const path = window.location.pathname;
      switch (path) {
        case '/privacy-policy':
          setCurrentPage('privacy-policy');
          break;
        case '/terms-of-service':
          setCurrentPage('terms-of-service');
          break;
        case '/risk-disclosure':
          setCurrentPage('risk-disclosure');
          break;
        case '/research':
        case '/research-blog':
          setCurrentPage('research-blog');
          break;
        default:
          setCurrentPage('home');
      }
      // Scroll to top when navigating via browser buttons
      window.scrollTo(0, 0);
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  // Render the appropriate component based on current page
  const renderPage = () => {
    switch (currentPage) {
      case 'privacy-policy':
        return <PrivacyPolicy />;
      case 'terms-of-service':
        return <TermsOfService />;
      case 'risk-disclosure':
        return <RiskDisclosure />;
      case 'research-blog':
        return <ResearchBlog onNavigate={handleNavigation} />;
      default:
        return <Home onNavigate={handleNavigation} />;
    }
  };

  return (
    <div style={{ position: "relative", minHeight: "100vh" }}>
      {/* AsciiRenderer background - home page only, fixed, behind content, non-interactive */}
      {currentPage === "home" && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            zIndex: 0,
            pointerEvents: "none",
          }}
        >
          {/* <AsciiRenderer
            modelUrl="/models/morhpeum.glb"
            {...ASCII_BG_CONFIG}
          /> */}
        </div>
      )}
      <div style={{ position: "relative", zIndex: 1 }}>
        <ParallaxProvider>
          {renderPage()}
        </ParallaxProvider>
      </div>
    </div>
  );
}

export default App;