import React, { useEffect, useRef } from 'react';
import { marked } from 'marked';
import mermaid from 'mermaid';

interface MarkdownViewerProps {
  content: string;
  className?: string;
}

export function MarkdownViewer({ content, className = '' }: MarkdownViewerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mermaidInitialized = useRef(false);

  useEffect(() => {
    // Initialize Mermaid once
    if (!mermaidInitialized.current) {
      mermaid.initialize({
        startOnLoad: false,
        theme: 'dark',
        securityLevel: 'loose',
        fontFamily: 'inherit',
        flowchart: {
          useMaxWidth: true,
          htmlLabels: true,
          curve: 'basis',
        },
      });
      mermaidInitialized.current = true;
    }
  }, []);

  useEffect(() => {
    if (!containerRef.current) return;

    // Parse markdown
    const html = marked.parse(content, {
      breaks: true,
      gfm: true,
    }) as string;

    // Set the HTML content
    containerRef.current.innerHTML = html;

    // Wrap tables in full-width container for maximum text display
    const tables = containerRef.current.querySelectorAll('table');
    tables.forEach((table) => {
      const wrapper = document.createElement('div');
      wrapper.className = 'markdown-table-wrapper';
      table.parentNode?.insertBefore(wrapper, table);
      wrapper.appendChild(table);
    });

    // Process Mermaid diagrams
    // Look for both <code class="language-mermaid"> and <pre><code class="language-mermaid">
    const mermaidCodeBlocks = containerRef.current.querySelectorAll('code.language-mermaid, pre code.language-mermaid');
    
    mermaidCodeBlocks.forEach((element, index) => {
      const mermaidCode = element.textContent || '';
      if (!mermaidCode.trim()) return;

      const mermaidId = `mermaid-${Date.now()}-${index}`;
      
      // Create a div for Mermaid to render into
      const mermaidDiv = document.createElement('div');
      mermaidDiv.className = 'mermaid';
      mermaidDiv.id = mermaidId;
      mermaidDiv.textContent = mermaidCode;
      
      // Replace the parent <pre> if it exists, otherwise replace the <code> element
      const parentPre = element.closest('pre');
      if (parentPre) {
        parentPre.replaceWith(mermaidDiv);
      } else if (element.parentElement) {
        element.parentElement.replaceWith(mermaidDiv);
      }
    });

    // Render all Mermaid diagrams after a short delay to ensure DOM is ready
    const mermaidDivs = containerRef.current.querySelectorAll('.mermaid');
    if (mermaidDivs.length > 0) {
      // Use setTimeout to ensure DOM updates are complete
      setTimeout(() => {
        mermaid.run({
          nodes: Array.from(mermaidDivs) as HTMLElement[],
        }).catch((error) => {
          console.error('Mermaid rendering error:', error);
        });
      }, 100);
    }
  }, [content]);

  return (
    <div
      ref={containerRef}
      className={`markdown-viewer ${className}`}
    />
  );
}
